contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testRegression_property() public {

        address[] memory accounts = new address[](1);
        accounts[0] = address(0xdead);
        uint256[] memory ids = new uint256[](2);
        ids[0] = 0;
        ids[1] = 1;

        bool reverted = false;
        try c.balanceOfBatch(accounts, ids) returns (uint256[] memory) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}
